{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined city.",
      "visual_description": "An ink-stained coat spread under lantern light, a brass compass pinning down a torn map showing broken towers and a distant bridge.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of the road ahead.",
      "visual_description": "A battered oil lamp on a rock, its single flame-eye glowing wide, casting long shadows toward the ruined skyline.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the cracked castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peeking around a shattered iron gate, key-wind tail ticking softly in the dusk.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver slips through a tall window.",
      "visual_description": "A figure in a clear diving helmet emerging from a pane of glass like water, coat rippling with reflections of broken city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "They meet in the abandoned plaza.",
      "visual_description": "Four companions gathered around a dry fountain, banners in tatters overhead, the lamp's eye lighting their faces.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Old royal banners flap above their heads.",
      "visual_description": "Faded crimson banners sagging between leaning towers, the tin fox sniffing the dusty cobblestones beneath them.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "A cursed tower hums with strange light.",
      "visual_description": "A spiral tower wrapped in green glow, cracks weeping pale mist, the diver studying his reflection in a curved window.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The lamp warns: do not climb the tower.",
      "visual_description": "The oracle lamp's flame stretching into a pointing shape, away from the glowing tower stairs, Mara pulling the diver back.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "They discover the sleeping tax collector.",
      "visual_description": "A round official slumped on a ledger pillow in a doorway, stamped papers stuck to his sleeves, snoring through a column of falling dust.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "He mumbles a key phrase in his sleep.",
      "visual_description": "Close-up of the tax collector's dreaming face with a paper labeled 'BRIDGE PASS' fluttering loose, the fox nipping it neatly free.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols march down the avenue.",
      "visual_description": "Tall lacquered helmets gleaming in torchlight at the end of a long street, the team pressed flat behind a toppled statue.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The diver pulls them through a shop mirror.",
      "visual_description": "A tall cracked mirror rippling like a pond, the diver guiding Mara's hand into the silver surface, the fox already half-vanished inside.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "They emerge before a sealed magic door.",
      "visual_description": "An arched door covered in glowing runes deep in a cellar, the oracle lamp held close, runes flickering as its flame-eye blinks.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The lamp recites the opening words.",
      "visual_description": "Runes peeling off the door as glowing letters, swirling into the lamp's flame, the fox bracing its paws to push the door inward.",
      "characters": ["oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, they find the captive they came for.",
      "visual_description": "A small chamber lit by the lamp's eye, chains lying broken where the diver kneels beside a slumped figure — the sleeping tax collector, dragged here without waking.",
      "characters": ["glass_diver", "sleeping_tax_collector", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Rumors of a great winged shadow chase them out.",
      "visual_description": "A massive scaled shadow sweeping across rooftops above, the team running along a parapet, the fox's tail spinning at full speed.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint for the long stone bridge.",
      "visual_description": "A cracked arched bridge stretching over a misted chasm at dawn, Mara hauling the still-snoring official, the diver shielding them with a mirror shard.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe across, the lamp dims with a satisfied wink.",
      "visual_description": "The far side of the bridge under a pale sunrise, the ruined city behind them, the oracle lamp's flame-eye narrowing to a small contented glow as the fox curls at Mara's boot.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

